mapper.select:
SELECT COUNT(1)
FROM ts_user_follow
WHERE follower_user_id = #{followerUserId}
  AND followed_user_id = #{followedUserId}
  AND status = 1

mapper.update:
UPDATE ts_user_follow
SET status = 0,
    updated_at = #{now}
WHERE follower_user_id = #{followerUserId}
  AND followed_user_id = #{followedUserId}
  AND status = 1
